  if(id==='X06'||id==='X07')return <section className="fd-reading fd-paper"><span className="fd-eyebrow">{c('Исследовать тему','Explore a topic')}</span><h2>{c(activeTopic.label[0],activeTopic.label[1])}</h2><p>{c(activeTopic.note[0],activeTopic.note[1])}</p><div className="fd-note"><Icon name="lock"/><p>{c('Ответы только для тебя. В профиль попадают только выбранные публичные баночки.','Answers are private. Only explicitly published jars appear in your profile.')}</p></div><div className="fd-info"><Icon name="clock"/>{c('3 вопроса · около 3 минут','3 questions · about 3 minutes')}</div>{button('Ответить на вопросы','Start questionnaire','X08',true)}<button className="fd-button" onClick={()=>openTopic(activeTopic.id,'X03')}>{c('Моя отметка','My entry')}</button></section>;
  if(id==='X08')return <QuestionnaireScene c={c} topic={activeTopic.id} index={question} answers={questionAnswers[activeTopic.id]?.[question]??[]} onAnswers={value=>setQuestionAnswers(old=>({...old,[activeTopic.id]:{...old[activeTopic.id],[question]:value}}))} onStep={setQuestion} onExit={()=>go('X07')} onFinish={()=>go('X09')}/>;
  if(id==='X09'||id==='X10'||id==='X11')return <div className="fd-reading fd-paper"><span className="fd-eyebrow">{c('Только для тебя','Only for you')}</span><h2>{c(activeTopic.label[0],activeTopic.label[1])}</h2><p>{c('Твои выбранные ответы. Интерес, опыт и границы остаются разными отметками; опрос не публикует их автоматически.','Your selected answers. Interest, experience and boundaries remain separate; the questionnaire never publishes them automatically.')}</p>{questionsForTopic(activeTopic.id).map((item,i)=><section key={i}><h3>{c(item.ru,item.en)}</h3><p>{questionAnswers[activeTopic.id]?.[i]?.length?questionAnswers[activeTopic.id]![i]!.map(a=>c(item.answers[a]![0],item.answers[a]![1])).join(' · '):c('Пока нет ответа','Not answered yet')}</p></section>)}{id==='X09'?<><button className="fd-primary" onClick={()=>openTopic(activeTopic.id,'X03')}>{c('Обновить свою баночку','Update my jar')}</button>{button('Поделиться выбранным','Share selected results','X11')}{button('В дневник','Open journal','X12')}</>:<>{chips([c(activeTopic.label[0],activeTopic.label[1])])}{formFields()}<button className="fd-primary" disabled={!checked.length} onClick={()=>record(id==='X10'?'Применение выбранных предложений в карту':'Публикация выбранных результатов',id==='X10'?'Applying selected map suggestions':'Sharing selected results')}>{c('Подтвердить выбранное','Confirm selected items')}</button></>}</div>;
  if(id==='X13'||id==='X14')return <div className="fd-editor">{(fields.X14??[]).map(field)}{chips([c('Доверие','Trust'),c('Границы','Boundaries'),c('Общение','Communication')])}<p>{c('Личный дневник видишь только ты. Публикация — отдельное действие.','Only you see your journal. Sharing requires a separate action.')}</p><button className="fd-primary" onClick={()=>record('Сохранение записи дневника','Saving a journal entry')}>{c('Сохранить запись','Save entry')}</button>{button('К дневнику','Back to journal','X12')}<button className="fd-danger" onClick={()=>overlay.open('O11')}>{c('Удалить запись','Delete entry')}</button></div>;
