  if(id==='G04')return saved.length?<>{saved.map(i=>postCard(i))}</>:empty('Вернуться к важному.','Return to what matters.','Сохрани то, к чему хочется вернуться.','Save something you want to return to.',button('Открыть ленту','Open feed','F01'));
  if(id==='Q01'||id==='Q02'||id==='Q07'||id==='Q06')return <div className="fd-editor"><Icon name="users" size={35}/><h2>{c('Вместе — по согласию обоих.','Together — with both partners’ consent.')}</h2><p>{c('Личные аккаунты, ответы и дневники остаются отдельными. Общие действия требуют двух решений.','Personal accounts, answers and journals remain separate. Shared actions need two decisions.')}</p>{formFields()}<button className={id==='Q06'?'fd-danger':'fd-primary'} onClick={()=>id==='Q06'?overlay.open('O22'):record('Приглашение пары и согласование общего действия','Partner invitations and shared approval')}>{id==='Q06'?c('Разъединить пару','Unlink partners'):id==='Q01'?c('Пригласить','Invite'):c('Согласовать','Approve')}</button>{button('Общий профиль','Couple profile','Q03')}{button('Вернуться','Go back','X01')}</div>;
  if(id==='M01')return <div className="fd-editor"><label className="fd-upload"><Icon name="plus" size={32}/><strong>{c('Выбрать фото или видео','Choose a photo or video')}</strong><input type="file" accept="image/*,video/*" onChange={e=>{if(e.target.files?.length)setLastAction(c('Материал выбран; загрузка не выполнена','File selected; upload has not been performed'));}}/></label>{formFields()}<button className="fd-primary" onClick={()=>record('Загрузка, проверка и публикация медиа','Media upload, review and publication')}>{c('Отправить материал','Upload media')}</button>{button('Состояние материала','Media status','M03')}</div>;
  if(id==='M02'||id==='M03')return empty(id==='M02'?'Материал по разрешению':'Проверка материала',id==='M02'?'Authorised media':'Media review','Новый материал остаётся приватным до выбора аудитории и необходимых проверок.','New media stays private until you select an audience and required checks are complete.',<>{button('Выбрать материал','Choose media','M01')}{button('Настройки доступа','Sharing settings','P04')}</>);
  if(id==='K01')return <div className="fd-settings-list">{[{id:'K02',ru:'Язык',en:'Language'},{id:'K03',ru:'Тема',en:'Appearance'},{id:'K04',ru:'Приватность',en:'Privacy'},{id:'K05',ru:'Уведомления',en:'Notifications'},{id:'K06',ru:'Безопасность и сессии',en:'Security and sessions'},{id:'K07',ru:'Мои данные',en:'Your data'},{id:'K08',ru:'Ссылки и сравнения',en:'Shared links'},{id:'B04',ru:'Подписка',en:'Membership'},{id:'S01',ru:'Помощь',en:'Help'}].map(v=><button key={v.id} onClick={()=>go(v.id as ScreenId)}>{c(v.ru,v.en)}<Icon name="arrow"/></button>)}<Link to="/account">{c('Аккаунт и выход','Account and sign out')}<Icon name="arrow"/></Link></div>;
