  if(id==='K03')return <div className="fd-editor"><div className="fd-theme-options">{(['light','dark','system'] as ThemePreference[]).map(v=><button key={v} aria-pressed={theme===v} onClick={()=>{setTheme(v);setThemePreference(v);}}><span className={'fd-theme-sample '+v}/>{v==='light'?c('Светлая','Light'):v==='dark'?c('Тёмная','Dark'):c('Как на устройстве','System')}</button>)}</div></div>;
