  if(id==='K06'||id==='K07'||id==='K08')return <div className="fd-editor">{id==='K06'?<><div className="fd-info"><Icon name="shield"/>{c('Текущая сессия · это устройство','Current session · this device')}</div><button className="fd-button" onClick={()=>record('Завершение других сессий','Ending other sessions')}>{c('Завершить другие сессии','End other sessions')}</button><Link className="fd-button" to="/account">{c('Настройки аккаунта','Account settings')}</Link></>:id==='K07'?<><button className="fd-button" onClick={()=>record('Экспорт личных данных','Exporting personal data')}>{c('Запросить экспорт','Request export')}</button><Link className="fd-danger" to="/account/delete">{c('Удалить аккаунт','Delete account')}</Link></>:<>{button('Создать ссылку','Create a link','X11')}{button('Посмотреть сравнение','View comparison','P05')}<button className="fd-danger" onClick={()=>overlay.open('O07')}>{c('Отозвать ссылку','Revoke link')}</button></>}</div>;
  if(id.startsWith('B'))return <div className="fd-premium"><span className="fd-premium-star"><Icon name="spark" size={40}/></span><span className="fd-eyebrow">FetUre Premium</span><h2>{id==='B02'?c('Больше запросов. Тот же выбор.','More requests. The same choice.'):id==='B03'?c('Подтверждение покупки','Purchase confirmation'):id==='B04'?c('Твои возможности','Your membership'):c('Больше пространства для знакомства.','More room to connect.')}</h2><p>{id==='B02'?c('В Free — 3 запроса за 24 часа. Premium расширяет лимит; одобрение всегда остаётся за другим человеком.','Free includes 3 requests per 24 hours. Premium extends the limit; the other person always decides.'):id==='B03'?c('Статус покупки и доступ обновляются после подтверждения. Здесь можно вернуться к условиям или проверить восстановление.','Purchase status and access update after confirmation. Return to the terms or check restoration here.'):id==='B04'?c('Посмотри условия, восстанови покупку или вернись к базовым возможностям.','Review terms, restore a purchase or return to the basic features.'):c('Дополнительные запросы доступа, история и сохранённые фильтры.','Additional sharing requests, history and saved filters.')}</p>{id==='B01'&&<div className="fd-plan-comparison"><div><span className="fd-eyebrow">Free</span><strong>{c('Знакомиться свободно','Connect freely')}</strong><small>{c('Лента, сообщества, карта и взаимные чаты','Feed, communities, map and mutual conversations')}</small></div><div><span className="fd-eyebrow">Premium</span><strong>{c('Больше возможностей','More possibilities')}</strong><small>{c('Больше запросов, история и сохранённые фильтры','More requests, history and saved filters')}</small></div></div>}<div className="fd-paper"><div className="fd-info"><Icon name="check"/>{c('Базовая приватность бесплатна','Basic privacy stays free')}</div><div className="fd-info"><Icon name="check"/>{c('Подписка не покупает чужое согласие','Membership never buys someone’s consent')}</div><div className="fd-info"><Icon name="check"/>{c('Взаимные чаты доступны без Premium','Mutual conversations do not require Premium')}</div></div><button className="fd-primary" onClick={()=>record('Оплата и проверка подписки не подключены; покупки не выполняются','Payments and membership verification are not connected; no purchase is made')}>{id==='B04'?c('Восстановить покупку','Restore purchase'):id==='B03'?c('Проверить покупку','Check purchase'):c('Посмотреть условия','View membership terms')}</button>{button('Без Premium','Continue without Premium','X01')}</div>;
