  if(id==='S03'||id==='S05')return empty(id==='S05'?'Этот материал недоступен':'Состояние обращения',id==='S05'?'This content is unavailable':'Report status',id==='S05'?'Вернись к предыдущему экрану или открой ленту.':'Решение и дальнейшие действия появятся после рассмотрения.',id==='S05'?'Go back or open the feed.':'A decision and next steps appear after review.',<>{button('В ленту','Open feed','F01')}{button('Помощь','Help','S01')}</>);
