  if(id==='A04')return <section className="fd-editor"><div className="fd-step"><span className="active">1</span><span>2</span><span>3</span></div><h2>{c('Как к тебе обращаться?','What should we call you?')}</h2><p>{c('Для начала достаточно ника и города. Полный профиль заполнишь позже.','Start with a nickname and city. Complete your profile later.')}</p>{field({ru:'Ник',en:'Nickname'})}{field({ru:'Город',en:'City'})}<button className="fd-primary" onClick={()=>{setDirty(false);go('A05');}}>{c('Продолжить','Continue')}</button></section>;
